/* 
  Using Mock Service Worker (MSW) to mock an API in a React Test 
*/
import { rest } from 'msw';
import { setupServer } from 'msw/node';

// 1. Define the fake API behavior
const server = setupServer(
  rest.get('/api/user', (req, res, ctx) => {
    return res(ctx.json({ firstName: 'Fake John' }));
  })
);

// 2. Start the interceptor before tests run
beforeAll(() => server.listen());

// 3. Test the Frontend UI. 
// The UI thinks it hit the real API, but MSW intercepted it!
it('displays the user name', async () => {
  render(<UserProfile />);
  expect(await screen.findByText('Fake John')).toBeInTheDocument();
});
